WITH input AS (SELECT jsonb_array_elements('[{"id":"YE11","description":"محافظة خضراء في المرتفعات الوسطى، معروفة بكثافة مدرجاتها الزراعية وتنوعها الطبيعي.\n\nتُظهر إب صورة مختلفة لليمن الجبلي: تجمع سكني كثيف نسبياً حول مدن وقرى على ارتفاعات متفاوتة، وتتصل حياة السكان بالمدرجات والأودية والطرق بين المرتفعات. من المفيد التمييز بين مركز المحافظة وبقية المديريات عند قراءة بياناتها.","old_description":"محافظة خضراء في المرتفعات الوسطى، معروفة بكثافة مدرجاتها الزراعية وتنوعها الطبيعي.","history":"ازدهرت مدن إب وجبلة ومناطقها على طرق التجارة والعلم، وتضم مباني ومساجد تاريخية بارزة.\n\nتمثل جبلة ومدينة إب محورين لفهم تاريخ العمران والعلم في المنطقة. ويُقرأ تراث القصور والمساجد والبلدات القديمة في سياق علاقات الحكم والتجارة في المرتفعات، لا باعتباره قائمة آثار منفصلة عن حياة الناس.","old_history":"ازدهرت مدن إب وجبلة ومناطقها على طرق التجارة والعلم، وتضم مباني ومساجد تاريخية بارزة.","geography":"تغلب عليها الجبال والأودية والمدرجات، وتحظى بأمطار موسمية أكثر من كثير من مناطق اليمن.\n\nتفسر اختلافات الارتفاع لماذا لا تتشابه الأمطار والزراعة داخل المحافظة؛ فالمدرجات تعتمد على تضاريس المنحدرات، بينما تستفيد الأودية من تجمع الجريان. ولا تكفي صورة محافظة خضراء للحكم على موارد المياه طوال السنة.","old_geography":"تغلب عليها الجبال والأودية والمدرجات، وتحظى بأمطار موسمية أكثر من كثير من مناطق اليمن.","economy":"ترتكز أنشطتها على الزراعة والتجارة والخدمات والحرف والسياحة الداخلية.\n\nيعتمد السكان على مزيج من الإنتاج الزراعي والتجارة والخدمات. وقد ترتبط أسواق المدن بمنتجات القرى المحيطة، ولذلك ينبغي عند تحليل الاقتصاد التمييز بين سبل عيش الأسر والإنتاج التجاري الكبير، وعدم افتراض تجانس المديريات.","old_economy":"ترتكز أنشطتها على الزراعة والتجارة والخدمات والحرف والسياحة الداخلية.","landmarks":"مدينة إب القديمة، جبلة، مسجد الملكة أروى، وادي بنا، بعدان وسمارة.\n\nمن المسارات المعرفية المفيدة الربط بين جبلة وتراث الملكة أروى، ومدينة إب القديمة، وطبيعة وادي بنا ومدرجات بعدان. ذكر هذه المواقع لا يعني أن الوصول إليها أو خدماتها السياحية متاحة حالياً؛ يلزم التحقق قبل أي زيارة.","old_landmarks":"مدينة إب القديمة، جبلة، مسجد الملكة أروى، وادي بنا، بعدان وسمارة."},{"id":"YE12","description":"محافظة جنوبية تمتد بين الساحل والمرتفعات، وتربط عدن بمناطق شبوة والبيضاء.\n\nيتغير طابع أبين بين ساحل بحر العرب والسهول الداخلية والجبال الشمالية؛ لذلك لا يمكن اختزالها في زنجبار أو منطقة ساحلية واحدة. يساعد هذا الامتداد على فهم تنوع القرى والأنشطة والمسافات بين المديريات.","old_description":"محافظة جنوبية تمتد بين الساحل والمرتفعات، وتربط عدن بمناطق شبوة والبيضاء.","history":"عرفت أبين تجمعات زراعية وتجارية قديمة، وظلت زنجبار مركزها الإداري الحديث.\n\nتعكس العلاقة بين زنجبار وجعار والقرى الزراعية تشكل مراكز إدارية وتجارية مرتبطة بالريف. لكن دراسة تاريخ المحافظة تتطلب الفصل بين تاريخ بلداتها، وتاريخ الأقاليم السياسية التي تعاقبت عليها، والوقائع المحلية الموثقة.","old_history":"عرفت أبين تجمعات زراعية وتجارية قديمة، وظلت زنجبار مركزها الإداري الحديث.","geography":"تجمع بين ساحل بحر العرب والأودية والسهول الزراعية، ثم ترتفع تضاريسها باتجاه الشمال.\n\nترتبط وديان أبين بانتقال المياه من المناطق المرتفعة إلى السهول؛ وهو ما يفسر حضور الأنشطة الزراعية في بعض المناطق دون غيرها. أما السواحل فتختلف بيئتها واحتياجاتها عن القرى الجبلية الشمالية.","old_geography":"تجمع بين ساحل بحر العرب والأودية والسهول الزراعية، ثم ترتفع تضاريسها باتجاه الشمال.","economy":"تعتمد الأنشطة المحلية على الزراعة وتربية الماشية وصيد الأسماك والتجارة الداخلية.\n\nتوفر الزراعة والصيد والرعي أسساً مختلفة لسبل العيش، وتشارك التجارة والخدمات في ربط الإنتاج بالأسواق المجاورة. ولا تكفي قائمة القطاعات لتقدير حجم التوظيف أو الإنتاج، ما لم تُراجع إحصاءات حديثة موثقة.","old_economy":"تعتمد الأنشطة المحلية على الزراعة وتربية الماشية وصيد الأسماك والتجارة الداخلية.","landmarks":"زنجبار، جعار، وادي بنا، شواطئ أبين والمناطق الزراعية المحيطة بها.\n\nتظهر زنجبار وجعار ووادي بنا والشريط الساحلي جوانب متمايزة من أبين: العمران والأسواق والزراعة والبحر. ينبغي النظر إلى المعالم بوصفها نقاطاً للدراسة المكانية، لا توصيات سفر أو تأكيداً لحالة الطرق والخدمات.","old_landmarks":"زنجبار، جعار، وادي بنا، شواطئ أبين والمناطق الزراعية المحيطة بها."},{"id":"YE13","description":"الوحدة الإدارية التي تضم مدينة صنعاء، المركز السياسي والثقافي والعمراني الأكبر في المرتفعات اليمنية.\n\nأمانة العاصمة وحدة إدارية حضرية منفصلة عن محافظة صنعاء المحيطة بها. هذا التمييز ضروري عند عرض المساحة والسكان والمديريات؛ فالإحصاءات التي تشمل صنعاء الحضرية لا يجوز نسبها تلقائياً إلى المحافظة الريفية المحيطة.","old_description":"الوحدة الإدارية التي تضم مدينة صنعاء، المركز السياسي والثقافي والعمراني الأكبر في المرتفعات اليمنية.","history":"تعد صنعاء من أقدم المدن المأهولة، وتتميز مدينتها القديمة بعمارتها البرجية وأسواقها ومساجدها.\n\nتمتاز صنعاء القديمة بالنسيج العمراني المتدرج والعمارة المبنية بمواد محلية والزخارف التي تميز واجهات المباني. وهي مدرجة على قائمة التراث العالمي لليونسكو منذ عام 1986، ما يجعل حماية نسيجها التاريخي موضوعاً قائماً بذاته.","old_history":"تعد صنعاء من أقدم المدن المأهولة، وتتميز مدينتها القديمة بعمارتها البرجية وأسواقها ومساجدها.","geography":"تقع في حوض جبلي مرتفع تحيط به الجبال، ويتميز مناخها بالاعتدال صيفاً والبرودة شتاءً.\n\nيسهم الحوض الجبلي المرتفع في اختلاف مناخ المدينة عن المناطق الساحلية اليمنية. تتداخل في المشهد الحضري أحياء قديمة وحديثة، ولا ينبغي الخلط بين حدود صنعاء القديمة وحدود أمانة العاصمة الإدارية.","old_geography":"تقع في حوض جبلي مرتفع تحيط به الجبال، ويتميز مناخها بالاعتدال صيفاً والبرودة شتاءً.","economy":"تتركز فيها الإدارة والخدمات والتجارة والصناعة والتعليم والثقافة.\n\nتؤدي المدينة أدواراً إدارية وتجارية وتعليمية وخدمية تتجاوز حدودها السكانية. لكن هذا الوصف لا يقدم تقديراً لحجم الاقتصاد الراهن أو عمل المؤسسات؛ فالحرب والتغيرات الإدارية تستدعي مراجع حديثة منفصلة.","old_economy":"تتركز فيها الإدارة والخدمات والتجارة والصناعة والتعليم والثقافة.","landmarks":"صنعاء القديمة، باب اليمن، الجامع الكبير، سوق الملح، قصر السلاح والمتاحف.\n\nيشكل باب اليمن والأسواق المحيطة والجامع الكبير والبيوت التاريخية مساراً لفهم البنية الحضرية للمدينة القديمة. ويمكن تتبع العلاقة بين الأسواق والحرف والمنازل دون افتراض أن جميع المواقع مفتوحة أو بحالة صون واحدة.","old_landmarks":"صنعاء القديمة، باب اليمن، الجامع الكبير، سوق الملح، قصر السلاح والمتاحف."},{"id":"YE14","description":"محافظة وسطية تتداخل فيها المرتفعات والهضاب، وتصل بين عدة أقاليم يمنية.\n\nتقع البيضاء عند التقاء أنماط جغرافية واجتماعية متعددة في وسط اليمن، بين مناطق مرتفعة ومسارات تتصل بمحافظات مجاورة. يساعد هذا الموقع على فهم تعدد المراكز المحلية وطرق العبور والتبادل.","old_description":"محافظة وسطية تتداخل فيها المرتفعات والهضاب، وتصل بين عدة أقاليم يمنية.","history":"كانت مناطق البيضاء جزءاً من مسارات تاريخية وقبلية مهمة، وتضم مواقع ومدناً ذات جذور قديمة.\n\nتعكس رداع وغيرها من البلدات القديمة مراحل متعاقبة من العمران والتبادل الثقافي. ومن المهم عند دراسة المحافظة فصل تراث الأبنية الإسلامية عن المواقع الأقدم، والرجوع إلى المراجع المتخصصة قبل إسناد تاريخ دقيق لأي مبنى.","old_history":"كانت مناطق البيضاء جزءاً من مسارات تاريخية وقبلية مهمة، وتضم مواقع ومدناً ذات جذور قديمة.","geography":"تتكون من جبال وهضاب وأودية زراعية، ويتفاوت مناخها بحسب الارتفاع والموقع.\n\nتتفاوت طبيعة الهضاب والمرتفعات والأودية، فتختلف فرص الزراعة وأنماط الاستقرار بحسب الماء والارتفاع. وليس للمحافظة مناخ واحد متجانس؛ فالسهول الداخلية تختلف عن القمم والمناطق الأكثر جفافاً.","old_geography":"تتكون من جبال وهضاب وأودية زراعية، ويتفاوت مناخها بحسب الارتفاع والموقع.","economy":"تشمل أنشطتها الزراعة والرعي والتجارة المحلية والحرف والخدمات.\n\nتُظهر الأسواق والأنشطة الزراعية والرعوية طبيعة اقتصاد يعتمد على الاتصال بين الريف والبلدات. وينبغي تجنب افتراض مساهمة رقمية لأي قطاع دون بيانات حديثة، خاصة في المناطق التي تأثرت حركة التجارة فيها.","old_economy":"تشمل أنشطتها الزراعة والرعي والتجارة المحلية والحرف والخدمات.","landmarks":"مدينة البيضاء، رداع، قلعة رداع، العامرية، والأودية والقرى الجبلية.\n\nتجمع رداع والبيضاء ومناطق الأودية بين التراث الحضري والبيئة الريفية. ويُعد جامع ومدرسة العامرية في رداع محوراً لفهم العمارة التاريخية، مع أهمية الاعتماد على مصادر متخصصة عند وصف حالته أو تاريخ ترميمه.","old_landmarks":"مدينة البيضاء، رداع، قلعة رداع، العامرية، والأودية والقرى الجبلية."},{"id":"YE15","description":"محافظة كثيفة السكان في جنوب غرب اليمن، تجمع بين مدينة تعز والمرتفعات والأودية وساحل البحر الأحمر.\n\nتجمع تعز بين مدينة كبيرة في المرتفعات ومناطق جبلية وزراعية وساحلية تصل إلى البحر الأحمر. لذلك فإن وصف المحافظة انطلاقاً من مركزها الحضري وحده يُخفي تنوع مناطق مثل المخا وجبل صبر والأودية الريفية.","old_description":"محافظة كثيفة السكان في جنوب غرب اليمن، تجمع بين مدينة تعز والمرتفعات والأودية وساحل البحر الأحمر.","history":"برزت تعز عاصمةً ومركزاً للعلم والتجارة في مراحل تاريخية مختلفة، واحتفظت بدور ثقافي مهم.\n\nارتبط صعود تعز بمراحل من الحكم اليمني شهدت نشاطاً عمرانياً وتعليمياً وتجارياً. ويكشف تراث قلعة القاهرة والمساجد والأحياء القديمة علاقة المدينة بالمراكز السياسية والأسواق، فيما للمخا تاريخ بحري وتجاري مختلف.","old_history":"برزت تعز عاصمةً ومركزاً للعلم والتجارة في مراحل تاريخية مختلفة، واحتفظت بدور ثقافي مهم.","geography":"تضم جبل صبر والمرتفعات الزراعية والأودية، وتمتد غرباً نحو المخا وساحل البحر الأحمر.\n\nيرتبط جبل صبر ببيئة مرتفعة تختلف عن ساحل المخا الأكثر حرارة؛ وبينهما أودية ومرتفعات وأراضٍ زراعية. ويساعد هذا التنوع على فهم اختلاف الموارد والأنشطة والطرق داخل المحافظة.","old_geography":"تضم جبل صبر والمرتفعات الزراعية والأودية، وتمتد غرباً نحو المخا وساحل البحر الأحمر.","economy":"تتنوع أنشطتها بين التجارة والصناعة والزراعة والخدمات والثقافة والموانئ.\n\nتلتقي التجارة والخدمات والصناعة الحضرية مع زراعة المناطق المرتفعة والأنشطة الساحلية والموانئ. ولا يصح من هذا الوصف وحده تقدير حجم اقتصاد تعز أثناء الحرب أو استمرارية خطوط الإمداد؛ يلزم رصد حديث.","old_economy":"تتنوع أنشطتها بين التجارة والصناعة والزراعة والخدمات والثقافة والموانئ.","landmarks":"قلعة القاهرة، جبل صبر، المدينة القديمة، جامع الجند، المخا وساحل البحر الأحمر.\n\nتمثل قلعة القاهرة وجبل صبر والجامع التاريخي في الجند ومدينة المخا محطات لدراسة أنماط مختلفة من تاريخ تعز. وترتبط المواقع الساحلية بتجارة البحر الأحمر، بينما تكشف المدينة القديمة المشهد المعماري الداخلي.","old_landmarks":"قلعة القاهرة، جبل صبر، المدينة القديمة، جامع الجند، المخا وساحل البحر الأحمر."},{"id":"YE16","description":"محافظة واسعة شمال شرقي صنعاء، وتتميز بامتدادها الصحراوي ومواقعها الأثرية القديمة.\n\nتتميز الجوف بمساحة واسعة قليلة التجانس البيئي في شمال شرق اليمن، حيث تجمع الصحاري والسهول والأودية تجمعات سكانية متباعدة. وهذا مهم عند قراءة توزيع الخدمات أو تقدير المسافات بين المديريات.","old_description":"محافظة واسعة شمال شرقي صنعاء، وتتميز بامتدادها الصحراوي ومواقعها الأثرية القديمة.","history":"كانت أجزاء من الجوف موطناً لممالك يمنية قديمة، وما زالت آثار المعابد والنقوش شاهدة على ذلك.\n\nتتيح براقش وقرناو والنقوش القديمة مدخلاً لدراسة ممالك جنوب الجزيرة العربية وشبكات التجارة قبل الإسلام. لكن ينبغي التمييز بين ما تثبته النقوش والآثار وما يرد في الروايات التاريخية اللاحقة.","old_history":"كانت أجزاء من الجوف موطناً لممالك يمنية قديمة، وما زالت آثار المعابد والنقوش شاهدة على ذلك.","geography":"تجمع بين الصحارى والسهول والأودية ومناطق زراعية متفرقة على أطراف المرتفعات.\n\nترسم الأودية مسارات للاستقرار والزراعة وسط نطاقات واسعة أكثر جفافاً. ويتباين استخدام الأرض بين مناطق الرعي والواحات والأطراف المرتفعة، فلا يكفي متوسط مناخي واحد لوصف المحافظة بأكملها.","old_geography":"تجمع بين الصحارى والسهول والأودية ومناطق زراعية متفرقة على أطراف المرتفعات.","economy":"تشمل الأنشطة الزراعة والرعي والتجارة المحلية واستغلال الموارد الطبيعية.\n\nتجمع الأنشطة الريفية بين الزراعة والرعي والتجارة، مع أهمية الحركة بين المناطق المتباعدة. وأي تقدير معاصر للموارد أو استخراجها يحتاج إلى مصادر كمية مستقلة، لا إلى استنتاجات من موقع المحافظة فقط.","old_economy":"تشمل الأنشطة الزراعة والرعي والتجارة المحلية واستغلال الموارد الطبيعية.","landmarks":"مدينة الحزم، براقش، قرناو، ومواقع المعابد والنقوش في وادي الجوف.\n\nتبرز مدينة الحزم وموقع براقش وقرناو ونطاقات وادي الجوف ضمن خريطة التراث والاستقرار. تُقرأ المواقع الأثرية بوصفها دلائل تاريخية تتطلب الحماية والتوثيق، لا بوصفها مزارات متاحة الزيارة تلقائياً.","old_landmarks":"مدينة الحزم، براقش، قرناو، ومواقع المعابد والنقوش في وادي الجوف."},{"id":"YE17","description":"محافظة شمال غربي اليمن تجمع بين الجبال المرتفعة وسهول تهامة والمناطق الساحلية.\n\nتضم حجة نطاقاً يمتد من مرتفعات جبلية إلى سهول تهامة وساحل البحر الأحمر؛ وهذا يخلق تبايناً واسعاً في الزراعة والمناخ وأنماط العمران. لا تمثل مدينة حجة المرتفعة الظروف نفسها التي تعيشها المجتمعات الساحلية.","old_description":"محافظة شمال غربي اليمن تجمع بين الجبال المرتفعة وسهول تهامة والمناطق الساحلية.","history":"ارتبطت حجة بالحصون والطرق التاريخية والأسواق التي تصل المرتفعات بالساحل الغربي.\n\nتشير الحصون والأسواق وطرق الوصل بين الجبال وتهامة إلى تاريخ من التبادل بين البيئات المختلفة. وعند كتابة تاريخ المحافظة ينبغي التمييز بين تاريخ المراكز الحضرية وتاريخ المجتمعات الريفية والساحلية.","old_history":"ارتبطت حجة بالحصون والطرق التاريخية والأسواق التي تصل المرتفعات بالساحل الغربي.","geography":"تتنوع تضاريسها من الجبال والمدرجات إلى الأودية والسهول الساحلية والجزر القريبة.\n\nيسهم اختلاف الارتفاع في انتقال المشهد من مدرجات على المنحدرات إلى سهول وأودية منخفضة قرب البحر الأحمر. وتتطلب المقارنات الزراعية والمائية النظر إلى هذه الأقاليم منفردة لا إلى متوسط واحد.","old_geography":"تتنوع تضاريسها من الجبال والمدرجات إلى الأودية والسهول الساحلية والجزر القريبة.","economy":"تعتمد على الزراعة والرعي وصيد الأسماك والتجارة والأسواق الريفية.\n\nتشمل سبل العيش الزراعة والرعي والتجارة والأسواق المحلية إلى جانب الصيد الساحلي. وقد تختلف فرص العمل وأنواع المحاصيل بين الجبال والساحل، لذلك لا تعكس قائمة واحدة وزن القطاعات في كل مديرية.","old_economy":"تعتمد على الزراعة والرعي وصيد الأسماك والتجارة والأسواق الريفية.","landmarks":"مدينة حجة، كحلان، عبس، ميدي، حرض والحصون والقرى الجبلية.\n\nتُظهر حجة وكحلان وعبس وميدي وحرض تنوع النطاقات الجغرافية من الجبال إلى الساحل والحدود. ويساعد ربط المعالم بالمديريات على فهم الامتداد الإداري، دون الحكم على إمكانية الوصول حالياً.","old_landmarks":"مدينة حجة، كحلان، عبس، ميدي، حرض والحصون والقرى الجبلية."},{"id":"YE18","description":"محافظة ساحلية واسعة على البحر الأحمر، وتعد الحديدة مركزها الحضري وميناءها الرئيسي.\n\nالحديدة محور ساحلي كبير على البحر الأحمر، وتجمع بين مدينة الميناء وامتداد زراعي وبحري واسع في تهامة. وتختلف صورة المحافظة في زبيد التاريخية عن المدينة الصناعية أو قرى السهل والجزر.","old_description":"محافظة ساحلية واسعة على البحر الأحمر، وتعد الحديدة مركزها الحضري وميناءها الرئيسي.","history":"شكّل ساحل تهامة ممراً تجارياً وبحرياً مهماً، ونمت مدنه حول الموانئ والأسواق والزراعة.\n\nتاريخ تهامة مرتبط بتجارة البحر الأحمر ونشاط الأسواق والزراعة. وتعد مدينة زبيد التاريخية أحد مواقع التراث العالمي لليونسكو منذ 1993، وهو ما يعطي صون عمرانها التقليدي أهمية تتجاوز المدينة نفسها.","old_history":"شكّل ساحل تهامة ممراً تجارياً وبحرياً مهماً، ونمت مدنه حول الموانئ والأسواق والزراعة.","geography":"تضم سهول تهامة الحارة وساحلاً طويلاً وجزراً وأودية تنحدر من المرتفعات الغربية.\n\nيهيمن المناخ الحار على السهل الساحلي، بينما تنقل الأودية مياه الأمطار من المرتفعات نحو تهامة. وتختلف الجزر والسواحل عن الداخل الزراعي في الموارد والأنشطة ومشكلات البنية التحتية.","old_geography":"تضم سهول تهامة الحارة وساحلاً طويلاً وجزراً وأودية تنحدر من المرتفعات الغربية.","economy":"تقوم أنشطتها على الموانئ وصيد الأسماك والزراعة والتجارة والصناعات والخدمات.\n\nالموانئ والصيد والأسواق الزراعية والتجارة عناصر مترابطة في اقتصاد المحافظة. لكن مكانة الميناء التاريخية لا تعني مستوى تشغيل راهناً محدداً؛ يجب الاعتماد على تقارير حديثة عند ذكر حركة السفن والتجارة أثناء النزاع.","old_economy":"تقوم أنشطتها على الموانئ وصيد الأسماك والزراعة والتجارة والصناعات والخدمات.","landmarks":"مدينة الحديدة، زبيد التاريخية، الخوخة، بيت الفقيه، جزيرة كمران وساحل البحر الأحمر.\n\nيمكن دراسة زبيد وبيت الفقيه وكمران والحواضر الساحلية لفهم أثر البحر والتجارة والتعليم التقليدي في تهامة. أما وصف شواطئ الخوخة وغيرها فيحتاج إلى الفصل بين أهميتها الجغرافية وظروف الوصول الفعلية.","old_landmarks":"مدينة الحديدة، زبيد التاريخية، الخوخة، بيت الفقيه، جزيرة كمران وساحل البحر الأحمر."},{"id":"YE19","description":"أكبر محافظات اليمن مساحة، وتمتد من ساحل بحر العرب إلى الأودية والهضاب والصحراء.\n\nتمتد حضرموت عبر ساحل بحر العرب والداخل الصحراوي والأودية الزراعية، وهي مساحة واسعة تحتضن أنماط عمران واقتصاد وثقافة متباينة. يختلف إقليم وادي حضرموت عن الساحل المحيط بالمكلا في التضاريس ونمط الاستقرار.","old_description":"أكبر محافظات اليمن مساحة، وتمتد من ساحل بحر العرب إلى الأودية والهضاب والصحراء.","history":"لحضرموت تاريخ طويل في التجارة والهجرة والعلم، وبرزت مدن الوادي والساحل كمراكز حضارية.\n\nتاريخ الوادي والساحل يتصل بالتجارة والهجرة والتعليم الديني والثقافي. وتعد مدينة شبام المسوّرة من مواقع التراث العالمي لليونسكو منذ 1982، بما تتميز به من بناء طيني مرتفع ومشهد عمراني متراص.","old_history":"لحضرموت تاريخ طويل في التجارة والهجرة والعلم، وبرزت مدن الوادي والساحل كمراكز حضارية.","geography":"تتنوع بين الساحل والهضبة الصحراوية ووادي حضرموت وروافده، مع تجمعات سكانية حول المدن والأودية.\n\nتقع التجمعات الزراعية في بعض بطون الأودية، فيما تشغل الهضاب والصحارى مساحات كبيرة، وتملك المدن الساحلية ظروفاً مناخية مختلفة. لذلك لا تعبر قيمة مطر أو حرارة واحدة عن المحافظة كلها.","old_geography":"تتنوع بين الساحل والهضبة الصحراوية ووادي حضرموت وروافده، مع تجمعات سكانية حول المدن والأودية.","economy":"تشمل أنشطتها النفط والغاز والصيد والتجارة والزراعة والخدمات والتحويلات والاستثمار.\n\nتجمع حضرموت بين الاقتصاد البحري والأسواق والخدمات والنشاط الزراعي وبعض موارد الطاقة، إلى جانب أثر الهجرة والتحويلات. ولا يجوز استنتاج حجم عائد النفط أو الدخل الحالي من مجرد وجود الموارد.","old_economy":"تشمل أنشطتها النفط والغاز والصيد والتجارة والزراعة والخدمات والتحويلات والاستثمار.","landmarks":"المكلا، شبام حضرموت، سيئون، تريم، وادي دوعن وشواطئ الساحل الحضرمي.\n\nتُظهر شبام وسيئون وتريم ووادي دوعن والمكلا وجوهاً متمايزة من حضرموت: العمارة الطينية، والمؤسسات العمرانية في الوادي، والواجهات الساحلية. ويحتاج كل موقع إلى معلومات صون ووصول حديثة عند الاستدلال السياحي.","old_landmarks":"المكلا، شبام حضرموت، سيئون، تريم، وادي دوعن وشواطئ الساحل الحضرمي."},{"id":"YE20","description":"محافظة مرتفعة جنوب صنعاء، تتميز بموقعها الزراعي والثقافي وبمدنها وأسواقها التاريخية.\n\nتمثل ذمار جزءاً من المرتفعات اليمنية الوسطى، حيث تمتزج القيعان الزراعية والمدن الداخلية والجبال. ويتصل تنوع مناطقها باختلاف درجات الحرارة وطرق الزراعة والعمران.","old_description":"محافظة مرتفعة جنوب صنعاء، تتميز بموقعها الزراعي والثقافي وبمدنها وأسواقها التاريخية.","history":"تضم ذمار مواقع من عصور يمنية متعددة، وكانت مركزاً للعلم والتجارة والحركة بين صنعاء والجنوب.\n\nتضم ذمار آثاراً ومواقع مرتبطة بفترات تاريخية متعددة، وترتبط مدينتها بأسواق وتعليم وحركة عبور بين صنعاء والجنوب. ويجب فصل تاريخ مواقع مثل بينون عن تاريخ المدينة الحديثة عند تقديم تسلسل زمني.","old_history":"تضم ذمار مواقع من عصور يمنية متعددة، وكانت مركزاً للعلم والتجارة والحركة بين صنعاء والجنوب.","geography":"تغلب عليها الهضاب والقيعان البركانية والجبال، ويتميز مناخها بالبرودة النسبية شتاءً.\n\nتنتشر القيعان والهضاب ضمن بيئة مرتفعة قد تكون باردة في الشتاء، مع مناطق بركانية ومعالم مائية حرارية. يفسر ذلك اختلاف الزراعة وأنماط العمران بين الأحواض والمنحدرات.","old_geography":"تغلب عليها الهضاب والقيعان البركانية والجبال، ويتميز مناخها بالبرودة النسبية شتاءً.","economy":"تشتهر بالزراعة وتربية الماشية والتجارة والحرف والصناعات الصغيرة.\n\nتشمل سبل العيش الزراعة والثروة الحيوانية والأسواق والحرف والصناعات الصغيرة. ولتقييم الإنتاجية الفعلية أو أثر تغير هطول الأمطار، ينبغي الاعتماد على سجلات متخصصة بدلاً من تعميم وصف المحافظة.","old_economy":"تشتهر بالزراعة وتربية الماشية والتجارة والحرف والصناعات الصغيرة.","landmarks":"مدينة ذمار، بينون، عنس، ضوران، حمامات دمت والمناطق البركانية.\n\nتقدم مدينة ذمار ومواقع بينون والمناطق المحيطة بعنس وضوران وحمامات دمت عناصر لدراسة التاريخ والاستقرار الجبلي والطبيعة البركانية. وتحتاج حالة المواقع إلى تحقق مستقل قبل أي استخدام سياحي.","old_landmarks":"مدينة ذمار، بينون، عنس، ضوران، حمامات دمت والمناطق البركانية."},{"id":"YE21","description":"محافظة واسعة جنوب شرقي اليمن تجمع بين الصحراء والجبال والأودية وساحل بحر العرب.\n\nتشغل شبوة نطاقاً واسعاً من جنوب شرق اليمن، يصل صحارى الداخل وسلاسله الجبلية بساحل بحر العرب. ومن ثم تختلف طبيعة بلدات الداخل عن تجمعات الصيد والساحل في طرق المعيشة والاتصال.","old_description":"محافظة واسعة جنوب شرقي اليمن تجمع بين الصحراء والجبال والأودية وساحل بحر العرب.","history":"كانت شبوة موطناً لمراكز من ممالك اليمن القديم، وارتبطت بطريق اللبان والتجارة الصحراوية.\n\nترتبط بعض مواقع شبوة بمراكز التجارة القديمة ومسارات مرور اللبان، بما في ذلك موقع مدينة شبوة القديمة. وينبغي قراءة هذا التراث من خلال الآثار والنقوش والبحوث التاريخية، لا مساواة المدينة القديمة بالمركز الإداري الحديث عتق.","old_history":"كانت شبوة موطناً لمراكز من ممالك اليمن القديم، وارتبطت بطريق اللبان والتجارة الصحراوية.","geography":"تتنوع بين الهضاب والصحارى والأودية الزراعية والساحل، مع تباين واضح بين الداخل والبحر.\n\nتضم المحافظة أودية وهضاباً وصحارى ومناطق ساحلية ذات ظروف مختلفة؛ ويتشكل الاستقرار حول موارد المياه ومسارات الحركة. ولا يمكن نقل بيانات الأراضي الزراعية أو المناخ الساحلي إلى كامل المساحة.","old_geography":"تتنوع بين الهضاب والصحارى والأودية الزراعية والساحل، مع تباين واضح بين الداخل والبحر.","economy":"تشمل أنشطتها النفط والغاز والزراعة والرعي والصيد والتجارة والخدمات.\n\nتتوزع الأنشطة بين الطاقة والتجارة والزراعة والرعي والصيد والخدمات، ويعتمد وزن كل نشاط على الموقع والزمن. يجب تجنب إيراد تقديرات حالية للإنتاج النفطي أو التشغيل دون بيانات قطاعية موثقة.","old_economy":"تشمل أنشطتها النفط والغاز والزراعة والرعي والصيد والتجارة والخدمات.","landmarks":"عتق، بيحان، مدينة شبوة القديمة، بلحاف، رضوم وساحل بحر العرب.\n\nيمكن الربط بين عتق وبيحان ومدينة شبوة القديمة وبلحاف ورضوم لشرح تنوع التاريخ الاقتصادي بين طرق القوافل والمنشآت الحديثة والمراكز الساحلية. لا تتضمن القائمة حكماً على توفر الخدمات أو إمكانية الزيارة.","old_landmarks":"عتق، بيحان، مدينة شبوة القديمة، بلحاف، رضوم وساحل بحر العرب."}]'::jsonb) AS obj),
changed AS (
UPDATE public.governorates g SET
description=p.obj->>'description',
history=p.obj->>'history',
geography=p.obj->>'geography',
economy=p.obj->>'economy',
landmarks=p.obj->>'landmarks',
revision=g.revision+1,updated_at=now()
FROM input p WHERE g.id=p.obj->>'id' AND g.description=p.obj->>'old_description' AND g.history=p.obj->>'old_history' AND g.geography=p.obj->>'old_geography' AND g.economy=p.obj->>'old_economy' AND g.landmarks=p.obj->>'old_landmarks'
RETURNING g.id
) SELECT (SELECT count(*) FROM input) planned,(SELECT count(*) FROM changed) updated;